w("""create or replace function tests.anon_reads() returns text language plpgsql as $$ declare t record; n bigint; err text := ''; begin
  for t in select c.relname from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relkind = 'r' loop
    begin execute format('select count(*) from public.%I', t.relname) into n; if n > 0 then err := err || t.relname || ' (' || n || ' lignes) '; end if;
    exception when insufficient_privilege then null; when others then err := err || t.relname || ' : ' || sqlerrm || ' '; end; end loop;
  return err; end $$;
grant execute on function tests.anon_reads() to anon;""")
